package com.xyzterm.logic;

import java.util.concurrent.atomic.AtomicLong;

/** Runs `DeepLinkCommandKt` and its Rust port side by side. Generated by rust-anything: call it in place of `DeepLinkCommandKt`. */
public final class DeepLinkCommandKtShadow {
    private DeepLinkCommandKtShadow() {}

    private static final String MODE = ("original".equals(System.getenv("RUST_ANYTHING_UNIT_VALIDATION")) ? "old" : System.getProperty("rust-anything.mode", "shadow"));
    public static final AtomicLong CALLS = new AtomicLong();
    public static final AtomicLong MISMATCHES = new AtomicLong();

    private static void compare(String name, Object expected, Object actual) {
        CALLS.incrementAndGet();
        if (actual instanceof Throwable || !rustanything.RustAnythingJson.write(expected).equals(rustanything.RustAnythingJson.write(actual))) {
            if (MISMATCHES.incrementAndGet() <= 10) {
                System.err.println("[rust-anything] mismatch in " + name + ": expected " + expected + ", got " + actual);
            }
        }
    }

    @SuppressWarnings("unchecked")
    public static boolean isValidDeepLinkCommand(String command) {
        if (MODE.equals("new")) {
            return (Boolean) rustanything.ValidationNative.call_isValidDeepLinkCommand(command);
        }
        boolean expected = DeepLinkCommandKt.isValidDeepLinkCommand(command);
        if (!MODE.equals("old")) {
            Object actual;
            try {
                actual = rustanything.ValidationNative.call_isValidDeepLinkCommand(command);
            } catch (RuntimeException e) {
                actual = e;
            }
            compare("isValidDeepLinkCommand", expected, actual);
        }
        return expected;
    }
}
